// UPS 价格表
import { upsPriceTable } from "./expressPricesUPS";

// 按渠道ID获取价格表
export function getPriceTable(carrierId: string): ExpressPriceTier[] {
  const id = carrierId.toLowerCase();
  if (id === "dhl") return dhlPriceTable;
  if (id === "fedex") return fedExPriceTable;
  if (id === "ups") return upsPriceTable;
  return [];
}

// 获取渠道对应的分区列表
export function getCarrierZones(carrierId: string): string[] {
  const id = carrierId.toLowerCase();
  if (id === "dhl") return dhlZones;
  if (id === "fedex") return fedExZones;
  if (id === "ups") return upsZones;
  return [];
}
